I.bnWho=el=>{S.modal.who=el.value};I.bnNotes=el=>{S.modal.notes=el.value};C.bnSvc=el=>{S.modal.svc=el.value;renderModal()};C.bnStaff=el=>{S.modal.staff=el.value};C.bnDate=el=>{S.modal.date=el.value};C.bnStart=el=>{S.modal.start=+el.value;renderModal()};
