A.bnSave=()=>{const m=S.modal;if(!m.who.trim()){m.err='Choose who the booking is for.';renderModal();return}const sv=D.services[m.camp].find(s=>s.n===m.svc);const clash=D.bookings.find(x=>x.camp===m.camp&&x.staff===m.staff&&x.date===m.date&&x.status!=='cancelled'&&m.start<x.start+x.dur&&x.start<m.start+sv.dur);
 if(clash){let n=m.start;while(D.bookings.some(x=>x.camp===m.camp&&x.staff===m.staff&&x.date===m.date&&x.status!=='cancelled'&&n<x.start+x.dur&&x.start<n+sv.dur)&&n<570)n+=30;m.err=`${esc(m.staff)} already has ${esc(clash.who)} at ${bkT(clash.start)}. The next free time is <b>${bkT(n)}</b> — it’s selected for you.`;m.start=n;renderModal();return}
 const b={id:uid('b'),camp:m.camp,staff:m.staff,svc:m.svc,who:m.who.trim(),cid:m.cid,date:m.date,start:m.start,dur:sv.dur,status:'booked',by:'You',created:'Sep 27',price:sv.price,conf:m.conf.slice()};D.bookings.push(b);S.bk.flash=[b.id];
 if(m.asg){const a=D.assigned.find(x=>x.id===m.asg);if(a)a.done=true;renderTop()}
 const cv=m.cid&&D.convos.find(v=>v.cid===m.cid);if(cv)cv.items.push(ev('book',`Appointment booked · ${dShort(b.date)} ${bkT(b.start)} · ${b.svc} with ${b.staff} · by you`,'now'));
 closeM();if(S.view==='bookings')rr();else if(S.view==='inbox')rr();toast(`Booked ${b.who} · ${dShort(b.date)} ${bkT(b.start)} — confirmation sent by ${m.conf.map(c=>({sms:'text',email:'email',wa:'WhatsApp'})[c]).join(', ')||'nothing'}. All agents see this time as taken.`)};
