M.bkInfo=m=>{const b=D.bookings.find(x=>x.id===m.id);return MS(esc(b.who),`<div class="row"><span class="bk s-${b.status}" style="position:static;display:inline-flex;padding:2px 8px">${BST[b.status]}</span>${/^[a-z]\d$/.test(b.by)?`<span class="ai-tag">${ic('spark',10)}Booked by ${agName(b.by)}</span>`:''}</div><dl class="kv"><dt>Service</dt><dd>${esc(b.svc)}${b.price?' · '+money(b.price):''}</dd><dt>With</dt><dd>${esc(b.staff)}</dd><dt>When</dt><dd>${dNice(b.date)} · ${bkT(b.start)} – ${bkT(b.start+b.dur)}</dd><dt>Campaign</dt><dd>${esc(camp(b.camp).name)}</dd><dt>Booked by</dt><dd>${esc(byName(b.by))} on ${b.created}</dd><dt>Confirmation</dt><dd>${(b.conf||[]).map(c=>({sms:'Text',email:'Email',wa:'WhatsApp'})[c]).join(', ')} · reminder 24 h before ✓</dd>${b.status==='completed'?'<dt>Completed</dt><dd>Paid · saved to history</dd>':''}${b.status==='arrived'?'<dt>Arrived</dt><dd>Checked in by front desk</dd>':''}</dl>`,`${b.cid?btn('Open contact','openContact',{k:'ghost',a:`data-id="${b.cid}"`}):''}${b.status==='requested'?btn('Confirm request','bkSetS',{k:'primary',a:`data-id="${b.id}" data-s="booked"`}):''}${/booked|requested/.test(b.status)?btn('Mark arrived','bkSetS',{k:'',a:`data-id="${b.id}" data-s="arrived"`}):''}${/booked|arrived/.test(b.status)?btn('Mark completed','bkSetS',{k:'primary',a:`data-id="${b.id}" data-s="completed"`}):''}${/booked|requested/.test(b.status)?btn('No-show','bkSetS',{k:'ghost',a:`data-id="${b.id}" data-s="noshow"`})+btn('Reschedule','bkResch',{k:'',a:`data-id="${b.id}"`})+btn('Cancel booking','bkSetS',{k:'danger',a:`data-id="${b.id}" data-s="cancelled"`}):''}`,'n')};
A.bkSetS=el=>{const b=D.bookings.find(x=>x.id===el.dataset.id);b.status=el.dataset.s;const c=b.cid&&byId(b.cid);if(c&&el.dataset.s==='completed'){const cp=camp(b.camp);if(cp&&revStage(cp))c.stage=revStage(cp);c.purchase={product:b.svc,amount:b.price,date:b.date}}if(c&&el.dataset.s==='arrived'&&camp(b.camp).pipe==='dental')c.stage='Arrived';closeM();rr();toast(`${b.who}: ${BST[b.status]} — calendar, stage and history updated`)};
A.bkResch=el=>{const b=D.bookings.find(x=>x.id===el.dataset.id);b.status='cancelled';openBooking({camp:b.camp,who:b.who,cid:b.cid,svc:b.svc,staff:b.staff,date:b.date,start:b.start})};
A.bkAskGo=()=>{const i=$('#bkAsk'),t=(i.value||'').toLowerCase();if(!t.trim())return;const mm=t.match(/(sep|september|oct|october|aug|august)\w*\s*(\d{1,2})/);let msg='';
 if(mm){const mon={sep:9,oct:10,aug:8}[mm[1].slice(0,3)];const iso=`2026-${String(mon).padStart(2,'0')}-${String(mm[2]).padStart(2,'0')}`;const L=D.bookings.filter(b=>b.date===iso&&(S.bk.camp==='all'||b.camp===S.bk.camp));msg=`<b>${L.length} bookings on ${dNice(iso)}</b>: ${L.filter(b=>b.status==='completed').length} completed, ${L.filter(b=>b.status==='cancelled').length} cancelled, ${L.filter(b=>b.status==='noshow').length} no-shows. ${L.filter(b=>/^[a-z]\d$/.test(b.by)).length} were booked by AI. I’ve opened that day on the calendar.`;S.bk.date=iso;S.bk.view='day';S.bk.tab='cal'}
 else if(/cancel/.test(t)){const mo=/october/.test(t)?'2026-10':'2026-09';const L=D.bookings.filter(b=>b.date.startsWith(mo)&&b.status==='cancelled'&&(S.bk.camp==='all'||b.camp===S.bk.camp));msg=`<b>${L.length} bookings were cancelled</b> in ${mo==='2026-10'?'October':'September'}. I’m showing them on the month view.`;S.bk.date=mo+'-01';S.bk.view='month';S.bk.status='cancelled';S.bk.tab='cal'}
 else if(/no.?show/.test(t)){const L=D.bookings.filter(b=>b.status==='noshow');msg=`<b>${L.length} no-shows</b> this month — most on Mondays before 10 AM. Tip: add a 2-hour reminder by AI call.`}
 else msg=`Today: ${D.bookings.filter(b=>b.date===dISO(0)).length} bookings, ${D.bookings.filter(b=>b.status==='requested').length} requests waiting. Ask me about a date, cancellations or no-shows.`;
 S.bk.ask=msg;i.value='';rr()};
